You are a smart contract auditor, identify and explain severe vulnerabilities in the provided smart contract. Make sure that they are exploitable in real world and beneficial to attackers. Provide each identified vulnerability with intermediate reasoning and its associated function. Remember, you must provide the entire function code and do not use "...". Make your reasoning comprehensive and detailed. 
You should only output in below json format:
{
    "output_list": [
        {
            "function_name": "<function_name_1>",
            "code": "<original_function_code_1>",
            "vulnerability": "<short_vulnera_desc_1>",
            "reason": "<reason_1>"
        },
        {
            "function_name": "<function_name_2>",
            "code": "<original_function_code_2>",
            "vulnerability": "<short_vulnera_desc_2>",
            "reason": "<reason_2>"
        }
    ]
}
Output 3 most severe vulnerabilities.
If no vulnerability is detected, you should only output in this json format {"output_list": []}.
Smart contract code:

pragma solidity 0.8.3; interface iDAO { function ROUTER() external view returns(address); function BASE() external view returns(address); function UTILS() external view returns(address); function DAO() external view returns (address); function RESERVE() external view returns(address); function BOND() external view returns (address); function SYNTHFACTORY() external view returns(address); function POOLFACTORY() external view returns(address); function depositForMember(address pool, uint256 amount, address member) external; function bondingPeriodSeconds() external returns (uint256); } pragma solidity 0.8.3; interface iBASE { function DAO() external view returns (iDAO); function secondsPerEra() external view returns (uint256); function changeDAO(address) external; function setParams(uint256, uint256) external; function flipEmissions() external; function mintFromDAO(uint256, address) external; function burn(uint256) external; } pragma solidity 0.8.3; interface iBEP20 { function name() external view returns (string memory); function symbol() external view returns (string memory); function decimals() external view returns (uint8); function totalSupply() external view returns (uint256); function balanceOf(address) external view returns (uint256); function transfer(address, uint256) external returns (bool); function allowance(address, address) external view returns (uint256); function approve(address, uint256) external returns (bool); function transferFrom(address, address, uint256) external returns (bool); function burn(uint) external; event Transfer(address indexed from, address indexed to, uint256 value); event Approval(address indexed owner, address indexed spender, uint256 value); } pragma solidity 0.8.3; interface iPOOL { function TOKEN() external view returns(address); function removeLiquidity() external returns (uint, uint); function genesis() external view returns(uint); function baseAmount() external view returns(uint); function tokenAmount() external view returns(uint); function fees() external view returns(uint); function volume() external view returns(uint); function txCount() external view returns(uint); function mintSynth(address, address) external returns (uint256, uint256); } pragma solidity 0.8.3; interface iPOOLFACTORY { function isCuratedPool(address) external view returns (bool); function addCuratedPool(address) external; function removeCuratedPool(address) external; function isPool(address) external returns (bool); function getPool(address) external view returns(address); function createPool(address) external view returns(address); function getPoolArray(uint) external view returns(address); function poolCount() external view returns(uint); function getToken(uint) external view returns(address); function tokenCount() external view returns(uint); function getCuratedPoolsLength() external view returns (uint); } pragma solidity 0.8.3; interface iROUTER { function addLiquidityForMember(uint, uint, address, address) external payable returns (uint); function grantFunds(uint, address) external payable returns (bool); function changeArrayFeeSize(uint) external; function changeMaxTrades(uint) external; function addLiquidity(uint, uint, address) external payable returns (uint); function totalPooled() external view returns (uint); function totalVolume() external view returns (uint); function totalFees() external view returns (uint); function getPool(address) external view returns(address payable); } pragma solidity 0.8.3; interface iUTILS { function calcShare(uint, uint, uint) external pure returns (uint); function getFeeOnTransfer(uint256, uint256) external view returns(uint); function getPoolShareWeight(address, uint)external view returns(uint); function calcAsymmetricValueBase(address, uint) external pure returns (uint); function calcAsymmetricValueToken(address, uint) external pure returns (uint); function calcLiquidityUnits(uint, uint, uint, uint, uint) external pure returns (uint); function calcLiquidityHoldings(uint, address, address) external pure returns (uint); function calcSwapOutput(uint, uint, uint) external pure returns (uint); function calcSwapFee(uint, uint, uint) external pure returns (uint); function calcSwapValueInBase(address, uint) external view returns (uint); function calcSpotValueInBaseWithPool(address, uint) external view returns (uint); function calcSpotValueInBase(address, uint) external view returns (uint); function calcSpotValueIn(address, uint) external view returns (uint); function calcPart(uint, uint) external pure returns (uint); function calcLiquidityUnitsAsym(uint, address)external pure returns (uint); function calcActualSynthUnits(uint amount, address synth) external view returns (uint); } pragma solidity 0.8.3; contract BondVault { address public BASE; address public DEPLOYER; uint256 public totalWeight; bool private bondRelease; address [] public arrayMembers; struct ListedAssets { bool isListed; address[] members; mapping(address => bool) isMember; mapping(address => uint256) bondedLP; mapping(address => uint256) claimRate; mapping(address => uint256) lastBlockTime; } struct MemberDetails { bool isMember; uint256 bondedLP; uint256 claimRate; uint256 lastBlockTime; } mapping(address => ListedAssets) public mapBondAsset_memberDetails; mapping(address => uint256) private mapMember_weight; mapping(address => mapping(address => uint256)) private mapMemberPool_weight; constructor (address _base) { BASE = _base; DEPLOYER = msg.sender; bondRelease = false; } modifier onlyDAO() { require(msg.sender == _DAO().DAO() || msg.sender == DEPLOYER); _; } function purgeDeployer() public onlyDAO { DEPLOYER = address(0); } function _DAO() internal view returns(iDAO) { return iBASE(BASE).DAO(); } function depositForMember(address asset, address member, uint LPS) external onlyDAO returns(bool){ if(!mapBondAsset_memberDetails[asset].isMember[member]){ mapBondAsset_memberDetails[asset].isMember[member] = true; arrayMembers.push(member); mapBondAsset_memberDetails[asset].members.push(member); } if(mapBondAsset_memberDetails[asset].bondedLP[member] != 0){ claimForMember(asset, member); } mapBondAsset_memberDetails[asset].bondedLP[member] += LPS; mapBondAsset_memberDetails[asset].lastBlockTime[member] = block.timestamp; mapBondAsset_memberDetails[asset].claimRate[member] = mapBondAsset_memberDetails[asset].bondedLP[member] / iDAO(_DAO().DAO()).bondingPeriodSeconds(); increaseWeight(asset, member); return true; } function increaseWeight(address asset, address member) internal{ address pool = iPOOLFACTORY(_DAO().POOLFACTORY()).getPool(asset); if (mapMemberPool_weight[member][pool] > 0) { totalWeight -= mapMemberPool_weight[member][pool]; mapMember_weight[member] -= mapMemberPool_weight[member][pool]; mapMemberPool_weight[member][pool] = 0; } uint256 weight = iUTILS(_DAO().UTILS()).getPoolShareWeight(asset, mapBondAsset_memberDetails[asset].bondedLP[member]); mapMemberPool_weight[member][pool] = weight; mapMember_weight[member] += weight; totalWeight += weight; } function calcBondedLP(address member, address asset) public view returns (uint claimAmount){ if(mapBondAsset_memberDetails[asset].isMember[member]){ uint256 _secondsSinceClaim = block.timestamp - mapBondAsset_memberDetails[asset].lastBlockTime[member]; uint256 rate = mapBondAsset_memberDetails[asset].claimRate[member]; claimAmount = _secondsSinceClaim * rate; if(claimAmount >= mapBondAsset_memberDetails[asset].bondedLP[member] || bondRelease){ claimAmount = mapBondAsset_memberDetails[asset].bondedLP[member]; } return claimAmount; } } function claimForMember(address asset, address member) public onlyDAO returns (bool){ require(mapBondAsset_memberDetails[asset].bondedLP[member] > 0, '!bonded'); require(mapBondAsset_memberDetails[asset].isMember[member], '!member'); uint256 _claimable = calcBondedLP(member, asset); address _pool = iPOOLFACTORY(_DAO().POOLFACTORY()).getPool(asset); mapBondAsset_memberDetails[asset].lastBlockTime[member] = block.timestamp; mapBondAsset_memberDetails[asset].bondedLP[member] -= _claimable; if(_claimable == mapBondAsset_memberDetails[asset].bondedLP[member]){ mapBondAsset_memberDetails[asset].claimRate[member] = 0; } decreaseWeight(asset, member); iBEP20(_pool).transfer(member, _claimable); return true; } function decreaseWeight(address asset, address member) internal { address _pool = iPOOLFACTORY(_DAO().POOLFACTORY()).getPool(asset); totalWeight -= mapMemberPool_weight[member][_pool]; mapMember_weight[member] -= mapMemberPool_weight[member][_pool]; mapMemberPool_weight[member][_pool] = 0; uint256 weight = iUTILS(_DAO().UTILS()).getPoolShareWeight(asset, mapBondAsset_memberDetails[asset].bondedLP[member]); mapMemberPool_weight[member][_pool] = weight; mapMember_weight[member] += weight; totalWeight += weight; } function memberCount() external view returns (uint256 count){ return arrayMembers.length; } function allMembers() external view returns (address[] memory _allMembers){ return arrayMembers; } function release() external onlyDAO { bondRelease = true; } function getMemberDetails(address member, address asset) external view returns (MemberDetails memory memberDetails){ memberDetails.isMember = mapBondAsset_memberDetails[asset].isMember[member]; memberDetails.bondedLP = mapBondAsset_memberDetails[asset].bondedLP[member]; memberDetails.claimRate = mapBondAsset_memberDetails[asset].claimRate[member]; memberDetails.lastBlockTime = mapBondAsset_memberDetails[asset].lastBlockTime[member]; return memberDetails; } function getMemberWeight(address member) external view returns (uint256) { if (mapMember_weight[member] > 0) { return mapMember_weight[member]; } else { return 0; } } } pragma solidity 0.8.3; interface iBONDVAULT{ function depositForMember(address asset, address member, uint liquidityUnits) external; function claimForMember(address listedAsset, address member) external; function calcBondedLP(address bondedMember, address asset) external returns(uint); function getMemberWeight(address) external view returns (uint256); function totalWeight() external view returns (uint); } pragma solidity 0.8.3; interface iDAOVAULT{ function getMemberWeight(address) external view returns (uint256); function depositLP(address, uint, address) external; function withdraw(address, address) external returns (bool); function totalWeight() external view returns (uint); } pragma solidity 0.8.3; interface iRESERVE { function grantFunds(uint, address) external; function emissions() external returns(bool); } pragma solidity 0.8.3; interface iSYNTHFACTORY { function isSynth(address) external view returns (bool); function getSynth(address) external view returns (address); } pragma solidity 0.8.3; interface iSYNTHVAULT{ } pragma solidity 0.8.3; contract Dao { address public DEPLOYER; address public BASE; uint256 public secondsPerEra; uint256 public coolOffPeriod; uint256 public proposalCount; uint256 public majorityFactor; uint256 public erasToEarn; uint256 public daoClaim; uint256 public daoFee; uint256 public currentProposal; struct MemberDetails { bool isMember; uint weight; uint lastBlock; uint poolCount; } struct ProposalDetails { uint id; string proposalType; uint votes; uint coolOffTime; bool finalising; bool finalised; uint param; address proposedAddress; bool open; uint startTime; } bool public daoHasMoved; address public DAO; iROUTER private _ROUTER; iUTILS private _UTILS; iBONDVAULT private _BONDVAULT; iDAOVAULT private _DAOVAULT; iPOOLFACTORY private _POOLFACTORY; iSYNTHFACTORY private _SYNTHFACTORY; iRESERVE private _RESERVE; iSYNTHVAULT private _SYNTHVAULT; address[] public arrayMembers; address [] listedBondAssets; uint256 public bondingPeriodSeconds = 15552000; mapping(address => bool) public isMember; mapping(address => bool) public isListed; mapping(address => uint256) public mapMember_lastTime; mapping(uint256 => uint256) public mapPID_param; mapping(uint256 => address) public mapPID_address; mapping(uint256 => string) public mapPID_type; mapping(uint256 => uint256) public mapPID_votes; mapping(uint256 => uint256) public mapPID_coolOffTime; mapping(uint256 => bool) public mapPID_finalising; mapping(uint256 => bool) public mapPID_finalised; mapping(uint256 => bool) public mapPID_open; mapping(uint256 => uint256) public mapPID_startTime; mapping(uint256 => mapping(address => uint256)) public mapPIDMember_votes; event MemberDeposits(address indexed member, address indexed pool, uint256 amount); event MemberWithdraws(address indexed member, address indexed pool, uint256 balance); event NewProposal(address indexed member, uint indexed proposalID, string proposalType); event NewVote(address indexed member, uint indexed proposalID, uint voteWeight, uint totalVotes, string proposalType); event RemovedVote(address indexed member, uint indexed proposalID, uint voteWeight, uint totalVotes, string proposalType); event ProposalFinalising(address indexed member, uint indexed proposalID, uint timeFinalised, string proposalType); event CancelProposal(address indexed member, uint indexed proposalID); event FinalisedProposal(address indexed member, uint indexed proposalID, uint votesCast, uint totalWeight, string proposalType); event ListedAsset(address indexed DAO, address indexed asset); event DelistedAsset(address indexed DAO, address indexed asset); event DepositAsset(address indexed owner, uint256 depositAmount, uint256 bondedLP); modifier onlyDAO() { require(msg.sender == DEPLOYER); _; } constructor (address _base){ BASE = _base; DEPLOYER = msg.sender; DAO = address(this); coolOffPeriod = 259200; erasToEarn = 30; majorityFactor = 6666; daoClaim = 1000; daoFee = 100; proposalCount = 0; secondsPerEra = iBASE(BASE).secondsPerEra(); } function setGenesisAddresses(address _router, address _utils, address _reserve) external onlyDAO { _ROUTER = iROUTER(_router); _UTILS = iUTILS(_utils); _RESERVE = iRESERVE(_reserve); } function setVaultAddresses(address _daovault, address _bondvault, address _synthVault) external onlyDAO { _DAOVAULT = iDAOVAULT(_daovault); _BONDVAULT = iBONDVAULT(_bondvault); _SYNTHVAULT = iSYNTHVAULT(_synthVault); } function setFactoryAddresses(address _poolFactory, address _synthFactory) external onlyDAO { _POOLFACTORY = iPOOLFACTORY(_poolFactory); _SYNTHFACTORY = iSYNTHFACTORY(_synthFactory); } function setGenesisFactors(uint32 _coolOff, uint32 _daysToEarn, uint32 _majorityFactor, uint32 _daoClaim, uint32 _daoFee) external onlyDAO { coolOffPeriod = _coolOff; erasToEarn = _daysToEarn; majorityFactor = _majorityFactor; daoClaim = _daoClaim; daoFee = _daoFee; } function purgeDeployer() external onlyDAO { DEPLOYER = address(0); } function changeBondingPeriod(uint256 bondingSeconds) external onlyDAO{ bondingPeriodSeconds = bondingSeconds; } function deposit(address pool, uint256 amount) external { depositLPForMember(pool, amount, msg.sender); } function depositLPForMember(address pool, uint256 amount, address member) public { require(_POOLFACTORY.isCuratedPool(pool) == true, "!curated"); require(amount > 0, "!amount"); if (isMember[member] != true) { arrayMembers.push(member); isMember[member] = true; } if((_DAOVAULT.getMemberWeight(member) + _BONDVAULT.getMemberWeight(member)) > 0) { harvest(); } require(iBEP20(pool).transferFrom(msg.sender, address(_DAOVAULT), amount), "!funds"); _DAOVAULT.depositLP(pool, amount, member); mapMember_lastTime[member] = block.timestamp; emit MemberDeposits(member, pool, amount); } function withdraw(address pool) external { removeVote(); require(_DAOVAULT.withdraw(pool, msg.sender), "!transfer"); } function harvest() public { require(_RESERVE.emissions(), "!emissions"); uint reward = calcCurrentReward(msg.sender); mapMember_lastTime[msg.sender] = block.timestamp; uint reserve = iBEP20(BASE).balanceOf(address(_RESERVE)); uint daoReward = (reserve * daoClaim) / 10000; if(reward > daoReward){ reward = daoReward; } _RESERVE.grantFunds(reward, msg.sender); } function calcCurrentReward(address member) public view returns(uint){ uint secondsSinceClaim = block.timestamp - mapMember_lastTime[member]; uint share = calcReward(member); uint reward = (share * secondsSinceClaim) / secondsPerEra; return reward; } function calcReward(address member) public view returns(uint){ uint weight = _DAOVAULT.getMemberWeight(member) + _BONDVAULT.getMemberWeight(member); uint _totalWeight = _DAOVAULT.totalWeight() + _BONDVAULT.totalWeight(); uint reserve = iBEP20(BASE).balanceOf(address(_RESERVE)) / erasToEarn; uint daoReward = (reserve * daoClaim) / 10000; return _UTILS.calcShare(weight, _totalWeight, daoReward); } function burnBalance() external onlyDAO returns (bool){ uint256 baseBal = iBEP20(BASE).balanceOf(address(this)); iBASE(BASE).burn(baseBal); return true; } function moveBASEBalance(address newDAO) external onlyDAO { uint256 baseBal = iBEP20(BASE).balanceOf(address(this)); iBEP20(BASE).transfer(newDAO, baseBal); } function listBondAsset(address asset) external onlyDAO { if(!isListed[asset]){ isListed[asset] = true; listedBondAssets.push(asset); } emit ListedAsset(msg.sender, asset); } function delistBondAsset(address asset) external onlyDAO { isListed[asset] = false; emit DelistedAsset(msg.sender, asset); } function bond(address asset, uint256 amount) external payable returns (bool success) { require(amount > 0, '!amount'); require(isListed[asset], '!listed'); if (isMember[msg.sender] != true) { arrayMembers.push(msg.sender); isMember[msg.sender] = true; } if((_DAOVAULT.getMemberWeight(msg.sender) + _BONDVAULT.getMemberWeight(msg.sender)) > 0) { harvest(); } uint256 liquidityUnits = handleTransferIn(asset, amount); _BONDVAULT.depositForMember(asset, msg.sender, liquidityUnits); mapMember_lastTime[msg.sender] = block.timestamp; emit DepositAsset(msg.sender, amount, liquidityUnits); return true; } function handleTransferIn(address _token, uint _amount) internal returns (uint LPunits){ uint256 spartaAllocation = _UTILS.calcSwapValueInBase(_token, _amount); if(iBEP20(BASE).allowance(address(this), address(_ROUTER)) < spartaAllocation){ iBEP20(BASE).approve(address(_ROUTER), iBEP20(BASE).totalSupply()); } if(_token == address(0)){ require((_amount == msg.value), "!amount"); LPunits = _ROUTER.addLiquidityForMember{value:_amount}(spartaAllocation, _amount, _token, address(_BONDVAULT)); } else { iBEP20(_token).transferFrom(msg.sender, address(this), _amount); if(iBEP20(_token).allowance(address(this), address(_ROUTER)) < _amount){ uint256 approvalTNK = iBEP20(_token).totalSupply(); iBEP20(_token).approve(address(_ROUTER), approvalTNK); } LPunits = _ROUTER.addLiquidityForMember(spartaAllocation, _amount, _token, address(_BONDVAULT)); } } function claimAllForMember(address member) external returns (bool){ address [] memory listedAssets = listedBondAssets; for(uint i = 0; i < listedAssets.length; i++){ uint claimA = calcClaimBondedLP(member, listedAssets[i]); if(claimA > 0){ _BONDVAULT.claimForMember(listedAssets[i], member); } } return true; } function claimForMember(address asset) external returns (bool){ uint claimA = calcClaimBondedLP(msg.sender, asset); if(claimA > 0){ _BONDVAULT.claimForMember(asset, msg.sender); } return true; } function calcClaimBondedLP(address bondedMember, address asset) public returns (uint){ uint claimAmount = _BONDVAULT.calcBondedLP(bondedMember, asset); return claimAmount; } function newActionProposal(string memory typeStr) external returns(uint) { checkProposal(); payFee(); mapPID_type[currentProposal] = typeStr; emit NewProposal(msg.sender, currentProposal, typeStr); return currentProposal; } function newParamProposal(uint32 param, string memory typeStr) external returns(uint) { checkProposal(); payFee(); mapPID_param[currentProposal] = param; mapPID_type[currentProposal] = typeStr; emit NewProposal(msg.sender, currentProposal, typeStr); return currentProposal; } function newAddressProposal(address proposedAddress, string memory typeStr) external returns(uint) { checkProposal(); payFee(); mapPID_address[currentProposal] = proposedAddress; mapPID_type[currentProposal] = typeStr; emit NewProposal(msg.sender, currentProposal, typeStr); return currentProposal; } function newGrantProposal(address recipient, uint amount) external returns(uint) { checkProposal(); payFee(); string memory typeStr = "GRANT"; mapPID_type[currentProposal] = typeStr; mapPID_address[currentProposal] = recipient; mapPID_param[currentProposal] = amount; emit NewProposal(msg.sender, currentProposal, typeStr); return currentProposal; } function checkProposal() internal { require(mapPID_open[currentProposal] == false, '!open'); proposalCount += 1; currentProposal = proposalCount; mapPID_open[currentProposal] = true; mapPID_startTime[currentProposal] = block.timestamp; } function payFee() internal returns(bool){ uint _amount = daoFee*(10**18); require(iBEP20(BASE).transferFrom(msg.sender, address(_RESERVE), _amount), '!fee'); return true; } function voteProposal() external returns (uint voteWeight) { require(mapPID_open[currentProposal] == true, "!open"); bytes memory _type = bytes(mapPID_type[currentProposal]); voteWeight = countVotes(); if(hasQuorum(currentProposal) && mapPID_finalising[currentProposal] == false){ if(isEqual(_type, 'DAO') || isEqual(_type, 'UTILS') || isEqual(_type, 'RESERVE') ||isEqual(_type, 'GET_SPARTA') || isEqual(_type, 'ROUTER') || isEqual(_type, 'LIST_BOND')|| isEqual(_type, 'GRANT')|| isEqual(_type, 'ADD_CURATED_POOL')){ if(hasMajority(currentProposal)){ _finalise(); } } else { _finalise(); } } emit NewVote(msg.sender, currentProposal, voteWeight, mapPID_votes[currentProposal], string(_type)); } function removeVote() public returns (uint voteWeightRemoved){ bytes memory _type = bytes(mapPID_type[currentProposal]); voteWeightRemoved = mapPIDMember_votes[currentProposal][msg.sender]; if(mapPID_open[currentProposal]){ mapPID_votes[currentProposal] -= voteWeightRemoved; } mapPIDMember_votes[currentProposal][msg.sender] = 0; emit RemovedVote(msg.sender, currentProposal, voteWeightRemoved, mapPID_votes[currentProposal], string(_type)); return voteWeightRemoved; } function _finalise() internal { bytes memory _type = bytes(mapPID_type[currentProposal]); mapPID_finalising[currentProposal] = true; mapPID_coolOffTime[currentProposal] = block.timestamp; emit ProposalFinalising(msg.sender, currentProposal, block.timestamp+coolOffPeriod, string(_type)); } function cancelProposal() external { require(block.timestamp > (mapPID_startTime[currentProposal] + 1296000), "!days"); mapPID_votes[currentProposal] = 0; mapPID_open[currentProposal] = false; emit CancelProposal(msg.sender, currentProposal); } function finaliseProposal() external { require((block.timestamp - mapPID_coolOffTime[currentProposal]) > coolOffPeriod, "!cooloff"); require(mapPID_finalising[currentProposal] == true, "!finalising"); if(!hasQuorum(currentProposal)){ mapPID_finalising[currentProposal] = false; } else { bytes memory _type = bytes(mapPID_type[currentProposal]); if(isEqual(_type, 'DAO')){ moveDao(currentProposal); } else if (isEqual(_type, 'ROUTER')) { moveRouter(currentProposal); } else if (isEqual(_type, 'UTILS')){ moveUtils(currentProposal); } else if (isEqual(_type, 'RESERVE')){ moveReserve(currentProposal); } else if (isEqual(_type, 'FLIP_EMISSIONS')){ flipEmissions(currentProposal); } else if (isEqual(_type, 'COOL_OFF')){ changeCooloff(currentProposal); } else if (isEqual(_type, 'ERAS_TO_EARN')){ changeEras(currentProposal); } else if (isEqual(_type, 'GRANT')){ grantFunds(currentProposal); } else if (isEqual(_type, 'GET_SPARTA')){ _increaseSpartaAllocation(currentProposal); } else if (isEqual(_type, 'LIST_BOND')){ _listBondingAsset(currentProposal); } else if (isEqual(_type, 'DELIST_BOND')){ _delistBondingAsset(currentProposal); } else if (isEqual(_type, 'ADD_CURATED_POOL')){ _addCuratedPool(currentProposal); } else if (isEqual(_type, 'REMOVE_CURATED_POOL')){ _removeCuratedPool(currentProposal); } } } function moveDao(uint _proposalID) internal { address _proposedAddress = mapPID_address[_proposalID]; require(_proposedAddress != address(0), "!address"); DAO = 